'use client';

import {
  DndContext,
  DragOverlay,
  MouseSensor,
  TouchSensor,
  pointerWithin,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragStartEvent,
} from '@dnd-kit/core';
import { LayoutGroup } from 'motion/react';
import { useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { useTimeouts } from '@/registry/ndeko/hooks/use-timeouts';
import { formatCost } from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import { laneLabelOf, LANES, RUN_TITLE, type LaneId } from './data';
import { BoardLane } from './lane';
import {
  INITIAL,
  LOOP_AFTER_MS,
  placementOf,
  reducer,
  RESTING,
  REWORK_MS,
  REWORK_USD,
  SCRIPT,
  tasksIn,
  type BoardState,
  type LastMove,
} from './session';
import { CARD_SURFACE, TaskCardBody } from './task-card';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const MOUSE = { activationConstraint: { distance: 4 } };

const TOUCH = { activationConstraint: { delay: 180, tolerance: 6 } };

function totalCostOf(state: BoardState) {
  let total = 0;
  for (const task of state.tasks) {
    total += task.costUsd;
  }
  return total;
}

function tasksWordOf(count: number) {
  if (count === 1) {
    return '1 task';
  }
  return `${count} tasks`;
}

function moveLineOf(lastMove: LastMove | null) {
  if (!lastMove) {
    return '';
  }
  return `${lastMove.title} moved to ${laneLabelOf(lastMove.lane)}`;
}

function laneIdOf(value: unknown) {
  const lane = LANES.find((candidate) => candidate.id === value);
  return lane?.id ?? null;
}

/** The drop glides the card to its new place; reduced motion puts it there at once. */
function dropAnimationOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return null;
  }
  return undefined;
}

export default function AgentOps08() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const { schedule } = useTimeouts();
  const shouldReduceMotion = usePrefersReducedMotion();
  const groupId = useId();
  const dndId = useId();
  const [draggedId, setDraggedId] = useState<string | null>(null);
  const sensors = useSensors(
    useSensor(MouseSensor, MOUSE),
    useSensor(TouchSensor, TOUCH)
  );
  const placement = placementOf(state);
  const draggedTask = state.tasks.find((task) => task.id === draggedId);
  const totalCost = formatCost(totalCostOf(state));
  const meta = `${tasksWordOf(state.tasks.length)} · ${totalCost} so far`;
  const moveLine = moveLineOf(state.lastMove);
  const message = spokenUnless(isAutoplaying, moveLine);
  const canReplay = isFinished && !isAutoplaying;

  function focusLater(selector: string) {
    requestAnimationFrame(() => {
      const target = ref.current?.querySelector<HTMLElement>(selector);
      target?.focus();
    });
  }

  /** An agent takes a task that came back to Running, reworks it and asks again. */
  function reworkIfRunning(id: string, lane: LaneId) {
    if (lane !== 'running') {
      return;
    }
    const resubmit = () => act({ type: 'submitted', id, usd: REWORK_USD });
    schedule(resubmit, REWORK_MS);
  }

  function sendBack(id: string, note: string) {
    act({ type: 'sentBack', id, note });
    reworkIfRunning(id, 'running');
  }

  function move(id: string, to: LaneId) {
    act({ type: 'moved', id, to });
    reworkIfRunning(id, to);
    focusLater(`[data-card-menu="${id}"]`);
  }

  function startDrag({ active }: DragStartEvent) {
    setDraggedId(String(active.id));
  }

  function endDrag({ active, over }: DragEndEvent) {
    setDraggedId(null);
    const to = laneIdOf(over?.id);
    if (!to) {
      return;
    }
    const id = String(active.id);
    act({ type: 'dropped', id, to });
    reworkIfRunning(id, to);
  }

  function cancelDrag() {
    setDraggedId(null);
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-5xl flex-col gap-4 p-4 @3xl:gap-5 @3xl:p-8'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
              <h1 className='text-lg font-semibold text-balance'>
                {RUN_TITLE}
              </h1>
              <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs tabular-nums'>
                {meta}
                <Badge variant='secondary'>Illustrative</Badge>
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay the run'
            />
          </header>

          <DndContext
            id={dndId}
            sensors={sensors}
            collisionDetection={pointerWithin}
            onDragStart={startDrag}
            onDragEnd={endDrag}
            onDragCancel={cancelDrag}
          >
            <LayoutGroup id={groupId}>
              <div className='grid grid-cols-1 gap-6 @3xl:min-h-[30rem] @3xl:grid-cols-3 @3xl:gap-3'>
                {LANES.map((lane) => (
                  <BoardLane
                    key={lane.id}
                    lane={lane}
                    tasks={tasksIn(state, lane.id)}
                    placement={placement}
                    pressed={pressed}
                    onApprove={(id) => act({ type: 'approved', id })}
                    onSendBack={sendBack}
                    onMove={move}
                  />
                ))}
              </div>
            </LayoutGroup>
            <DragOverlay dropAnimation={dropAnimationOf(shouldReduceMotion)}>
              {draggedTask && (
                <div className={cn(CARD_SURFACE, 'cursor-grabbing')}>
                  <TaskCardBody task={draggedTask} isOverlay />
                </div>
              )}
            </DragOverlay>
          </DndContext>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { useDraggable, useDroppable } from '@dnd-kit/core';
import { LayoutGroup, motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { springOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Lane, LaneId } from './data';
import type { Task } from './session';
import { cardClassOf, TaskCardBody } from './task-card';

const LANE_DOT: Record<LaneId, string> = {
  running: 'bg-info',
  review: 'bg-warning',
  done: 'bg-success',
};

function tasksWordOf(count: number) {
  if (count === 1) {
    return 'task';
  }
  return 'tasks';
}

/** The ring shows the target at every width; the tray only exists side by side. */
function laneToneOf(isTarget: boolean) {
  if (isTarget) {
    return 'ring-primary/25 ring-2 @3xl:bg-primary/[0.06]';
  }
  return 'ring-0 ring-transparent @3xl:bg-foreground/[0.03]';
}

function slotToneOf(isTarget: boolean) {
  if (isTarget) {
    return 'border-primary/40';
  }
  return 'border-foreground/20';
}

type DraggableCardProps = {
  task: Task;
  placement: string;
  travel: Transition;
  pressed: string | null;
  onApprove: (id: string) => void;
  onSendBack: (id: string, note: string) => void;
  onMove: (id: string, to: LaneId) => void;
};

/**
 * A card that changes lane keeps its layout id, so it travels to its new place. A card a person
 * dropped takes a new one: it is already where it was let go.
 */
function DraggableCard({
  task,
  placement,
  travel,
  pressed,
  onApprove,
  onSendBack,
  onMove,
}: DraggableCardProps) {
  const { setNodeRef, listeners, isDragging } = useDraggable({ id: task.id });

  return (
    <motion.li
      layout='position'
      layoutId={`${task.id}:${task.drops}`}
      layoutDependency={placement}
      transition={{ layout: travel }}
      className='relative'
    >
      <div
        ref={setNodeRef}
        {...listeners}
        className={cn(
          'cursor-grab touch-manipulation select-none active:cursor-grabbing',
          cardClassOf(isDragging)
        )}
      >
        <TaskCardBody
          task={task}
          pressed={pressed}
          onApprove={onApprove}
          onSendBack={onSendBack}
          onMove={onMove}
        />
      </div>
    </motion.li>
  );
}

export type BoardLaneProps = {
  lane: Lane;
  tasks: Task[];
  /** Where every task sits: the cards and the lane header measure again when it changes. */
  placement: string;
  pressed: string | null;
  onApprove: (id: string) => void;
  onSendBack: (id: string, note: string) => void;
  onMove: (id: string, to: LaneId) => void;
};

/** A lane takes a drop anywhere, even when it is empty. On a phone the lanes stack and lose their tray. */
export function BoardLane({
  lane,
  tasks,
  placement,
  pressed,
  onApprove,
  onSendBack,
  onMove,
}: BoardLaneProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const travel = springOf(shouldReduceMotion);
  const { setNodeRef, isOver } = useDroppable({ id: lane.id });
  const count = tasks.length;
  const isEmpty = count === 0;

  return (
    <section
      ref={setNodeRef}
      aria-label={lane.label}
      className={cn(
        'flex flex-col gap-2 rounded-xl transition-[background-color,box-shadow] duration-150 @3xl:p-2',
        laneToneOf(isOver)
      )}
    >
      <motion.header
        layout='position'
        layoutDependency={placement}
        transition={{ layout: travel }}
        className='flex h-8 items-center gap-2 @3xl:px-1'
      >
        <span
          aria-hidden='true'
          className={cn('size-2 shrink-0 rounded-full', LANE_DOT[lane.id])}
        />
        <h2 className='text-[13px] font-medium'>{lane.label}</h2>
        <LayoutGroup inherit={false}>
          <span className='bg-foreground/[0.06] text-muted-foreground inline-flex h-5 min-w-5 items-center justify-center rounded-sm px-1.5 text-xs'>
            <MotionNumber value={count} />
            <span className='sr-only'> {tasksWordOf(count)}</span>
          </span>
        </LayoutGroup>
      </motion.header>
      <ul className='flex flex-col gap-2'>
        {tasks.map((task) => (
          <DraggableCard
            key={task.id}
            task={task}
            placement={placement}
            travel={travel}
            pressed={pressed}
            onApprove={onApprove}
            onSendBack={onSendBack}
            onMove={onMove}
          />
        ))}
      </ul>
      {isEmpty && (
        <p
          className={cn(
            'hairline-border text-muted-foreground flex min-h-16 items-center justify-center rounded-lg border-dashed px-3 py-2 text-center text-xs transition-colors duration-150',
            slotToneOf(isOver)
          )}
        >
          {lane.emptyLine}
        </p>
      )}
    </section>
  );
}

'use client';

import { useId, useRef, useState } from 'react';

import { formatCost, seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { CheckIcon, EllipsisIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';
import { Fold } from '@/registry/ndeko/ui/chat-motion';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/registry/ndeko/ui/dropdown-menu';
import { Input } from '@/registry/ndeko/ui/input';
import { LiveDuration } from '@/registry/ndeko/ui/live-duration';

import { AGENTS, LANES, type AgentId, type LaneId } from './data';
import type { Task } from './session';

export const CARD_SURFACE =
  'bg-card hairline-ring ring-border rounded-lg shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.04]';

type GemStyle = React.CSSProperties & { '--gem': string };

function sentBackLineOf(note: string | undefined) {
  const hasText = note !== undefined && note !== '';
  if (hasText) {
    return `Sent back by you: ${note}`;
  }
  return 'Sent back by you';
}

function AgentChip({ agentId }: { agentId: AgentId }) {
  const agent = AGENTS[agentId];
  const gemStyle: GemStyle = { '--gem': seriesColorOf(agent.series) };

  return (
    <span className='flex min-w-0 items-center gap-1.5 text-xs font-medium'>
      <span
        aria-hidden='true'
        style={gemStyle}
        className='gem-plate inline-flex size-5 shrink-0 items-center justify-center rounded-[5px] text-[10px] font-semibold select-none'
      >
        {agent.initial}
      </span>
      <span className='truncate'>{agent.name}</span>
    </span>
  );
}

type ApprovalProps = {
  task: Task;
  isApprovePressed: boolean;
  onApprove: (id: string) => void;
  onSendBack: (id: string, note: string) => void;
};

function Approval({
  task,
  isApprovePressed,
  onApprove,
  onSendBack,
}: ApprovalProps) {
  const noteId = useId();
  const noteRef = useRef<HTMLInputElement>(null);
  const [isAsking, setIsAsking] = useState(false);
  const [note, setNote] = useState('');

  /** The buttons leave when the field unfolds, so the focus goes to the field. */
  function ask() {
    setIsAsking(true);
    requestAnimationFrame(() => noteRef.current?.focus());
  }

  function sendBack(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    onSendBack(task.id, note.trim());
  }

  return (
    <div className='bg-warning/10 flex flex-col gap-2 rounded-md p-2.5 transition-opacity duration-300 starting:opacity-0'>
      <p className='text-xs leading-5'>{task.request}</p>
      {!isAsking && (
        <div className='flex flex-wrap items-center gap-2'>
          <Button
            type='button'
            size='sm'
            onClick={() => onApprove(task.id)}
            className={pressedSolidOf(isApprovePressed)}
          >
            Approve
          </Button>
          <Button type='button' size='sm' variant='outline' onClick={ask}>
            Request changes
          </Button>
        </div>
      )}
      <Fold open={isAsking}>
        <form onSubmit={sendBack} className='flex flex-col gap-2'>
          <label htmlFor={noteId} className='sr-only'>
            What should change
          </label>
          <Input
            id={noteId}
            ref={noteRef}
            size='sm'
            autoComplete='off'
            placeholder='What should change?'
            value={note}
            onChange={(event) => setNote(event.target.value)}
          />
          <div className='flex items-center gap-2'>
            <Button type='submit' size='sm'>
              Send back
            </Button>
            <Button
              type='button'
              size='sm'
              variant='ghost'
              onClick={() => setIsAsking(false)}
            >
              Cancel
            </Button>
          </div>
        </form>
      </Fold>
    </div>
  );
}

export type TaskCardBodyProps = {
  task: Task;
  pressed?: string | null;
  /** The copy under the pointer shows the task and nothing to press. */
  isOverlay?: boolean;
  onApprove?: (id: string) => void;
  onSendBack?: (id: string, note: string) => void;
  onMove?: (id: string, to: LaneId) => void;
};

function noop() {}

export function TaskCardBody({
  task,
  pressed = null,
  isOverlay = false,
  onApprove = noop,
  onSendBack = noop,
  onMove = noop,
}: TaskCardBodyProps) {
  const isRunning = task.lane === 'running';
  const isInReview = task.lane === 'review';
  const isDone = task.lane === 'done';
  const showsApproval = isInReview && !isOverlay;
  const showsApproved = isDone && task.wasApproved;
  const hasNote = task.note !== undefined;
  const otherLanes = LANES.filter((lane) => lane.id !== task.lane);

  return (
    <div className='flex flex-col gap-2 p-2.5'>
      <div className='flex items-center gap-2'>
        <AgentChip agentId={task.agentId} />
        {!isOverlay && (
          <DropdownMenu>
            <DropdownMenuTrigger
              render={
                <Button
                  type='button'
                  variant='ghost'
                  size='icon-sm'
                  data-card-menu={task.id}
                  aria-label={`Move ${task.title}`}
                  className='text-muted-foreground -my-1 ms-auto -me-1 size-6'
                />
              }
            >
              <EllipsisIcon />
            </DropdownMenuTrigger>
            <DropdownMenuContent align='end' className='min-w-44'>
              {otherLanes.map((lane) => (
                <DropdownMenuItem
                  key={lane.id}
                  onClick={() => onMove(task.id, lane.id)}
                >
                  Move to {lane.label}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </div>
      <p className='text-[13px] leading-5 font-medium text-pretty'>
        {task.title}
      </p>
      {hasNote && (
        <p className='text-muted-foreground text-xs leading-5'>
          {sentBackLineOf(task.note)}
        </p>
      )}
      <p className='text-muted-foreground flex items-center gap-2 text-xs'>
        <LiveDuration item={task} isRunning={isRunning} />
        <span aria-hidden='true'>·</span>
        <span className='tabular-nums'>{formatCost(task.costUsd)}</span>
        {showsApproved && (
          <span className='ms-auto flex items-center gap-1'>
            <CheckIcon className='text-success-foreground size-3.5' />
            Approved by you
          </span>
        )}
      </p>
      {showsApproval && (
        <Approval
          task={task}
          isApprovePressed={pressed === `approve-${task.id}`}
          onApprove={onApprove}
          onSendBack={onSendBack}
        />
      )}
    </div>
  );
}

export function cardClassOf(isDragging: boolean) {
  return cn(CARD_SURFACE, isDragging && 'opacity-40');
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import { TASKS, type AgentId, type LaneId, type TaskSeed } from './data';

export type Task = {
  id: string;
  agentId: AgentId;
  title: string;
  lane: LaneId;
  costUsd: number;
  startedAt: number;
  endedAt?: number;
  request: string;
  /** What a person asked for when they sent the task back. */
  note?: string;
  wasApproved: boolean;
  /** Counts the drops: a dropped card lands where it was let go, it does not travel from its lane. */
  drops: number;
};

export type LastMove = {
  title: string;
  lane: LaneId;
};

export type BoardState = {
  /** In the order of the lanes: a task that changes lane goes to the end of its new one. */
  tasks: Task[];
  lastMove: LastMove | null;
};

export type BoardAction =
  | { type: 'submitted'; id: string; usd: number }
  | { type: 'spent'; id: string; usd: number }
  | { type: 'approved'; id: string }
  | { type: 'sentBack'; id: string; note: string }
  | { type: 'moved'; id: string; to: LaneId }
  | { type: 'dropped'; id: string; to: LaneId };

type Step = SessionStep<BoardState, BoardAction>;

const MINUTE_MS = 60_000;

const LOADED_AT = Date.now();

function since(minutes: number) {
  return LOADED_AT - minutes * MINUTE_MS;
}

function endedAtOf(seed: TaskSeed) {
  if (seed.endedAgo === undefined) {
    return undefined;
  }
  return since(seed.endedAgo);
}

function taskOf(seed: TaskSeed): Task {
  return {
    id: seed.id,
    agentId: seed.agentId,
    title: seed.title,
    lane: seed.lane,
    costUsd: seed.costUsd,
    startedAt: since(seed.startedAgo),
    endedAt: endedAtOf(seed),
    request: seed.request,
    wasApproved: seed.lane === 'done',
    drops: 0,
  };
}

export const INITIAL: BoardState = {
  tasks: TASKS.map(taskOf),
  lastMove: null,
};

export function tasksIn(state: BoardState, lane: LaneId) {
  return state.tasks.filter((task) => task.lane === lane);
}

/** Where every task sits. Cards only measure themselves again when it changes. */
export function placementOf(state: BoardState) {
  const places = state.tasks.map((task) => `${task.id}:${task.lane}`);
  return places.join(' ');
}

function taskById(state: BoardState, id: string) {
  return state.tasks.find((task) => task.id === id);
}

/** Work stops the clock when a task leaves Running and starts it again when it comes back. */
function timedFor(task: Task, lane: LaneId, now: number): Task {
  if (lane === 'running') {
    return { ...task, lane, endedAt: undefined };
  }
  return { ...task, lane, endedAt: task.endedAt ?? now };
}

function relocated(
  state: BoardState,
  id: string,
  change: (task: Task) => Task
): BoardState {
  const task = taskById(state, id);
  if (!task) {
    return state;
  }
  const next = change(task);
  const others = state.tasks.filter((candidate) => candidate.id !== id);
  const lastMove = { title: next.title, lane: next.lane };
  return { tasks: [...others, next], lastMove };
}

function submitted(
  state: BoardState,
  id: string,
  usd: number,
  now: number
): BoardState {
  const task = taskById(state, id);
  if (task?.lane !== 'running') {
    return state;
  }
  return relocated(state, id, (current) => ({
    ...timedFor(current, 'review', now),
    costUsd: current.costUsd + usd,
  }));
}

function spent(state: BoardState, id: string, usd: number): BoardState {
  const tasks = state.tasks.map((task) => {
    const isWorking = task.id === id && task.lane === 'running';
    if (isWorking) {
      return { ...task, costUsd: task.costUsd + usd };
    }
    return task;
  });
  return { ...state, tasks };
}

function approved(state: BoardState, id: string, now: number): BoardState {
  const task = taskById(state, id);
  if (task?.lane !== 'review') {
    return state;
  }
  return relocated(state, id, (current) => ({
    ...timedFor(current, 'done', now),
    wasApproved: true,
    note: undefined,
  }));
}

function sentBack(
  state: BoardState,
  id: string,
  note: string,
  now: number
): BoardState {
  const task = taskById(state, id);
  if (task?.lane !== 'review') {
    return state;
  }
  return relocated(state, id, (current) => ({
    ...timedFor(current, 'running', now),
    note,
  }));
}

function moved(
  state: BoardState,
  id: string,
  to: LaneId,
  now: number,
  isDrop: boolean
): BoardState {
  const task = taskById(state, id);
  const isSameLane = task?.lane === to;
  if (!task || isSameLane) {
    return state;
  }
  let drops = task.drops;
  if (isDrop) {
    drops += 1;
  }
  return relocated(state, id, (current) => ({
    ...timedFor(current, to, now),
    wasApproved: to === 'done',
    drops,
  }));
}

export function applyAt(
  state: BoardState,
  action: BoardAction,
  now: number
): BoardState {
  switch (action.type) {
    case 'submitted':
      return submitted(state, action.id, action.usd, now);
    case 'spent':
      return spent(state, action.id, action.usd);
    case 'approved':
      return approved(state, action.id, now);
    case 'sentBack':
      return sentBack(state, action.id, action.note, now);
    case 'moved':
      return moved(state, action.id, action.to, now, false);
    case 'dropped':
      return moved(state, action.id, action.to, now, true);
  }
}

export function reducer(state: BoardState, action: BoardAction) {
  return applyAt(state, action, Date.now());
}

function hasLeftReview(id: string) {
  return (state: BoardState) => taskById(state, id)?.lane !== 'review';
}

